head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.BAS_YY = "";
scwin.COM_NM = "";
scwin.ANULFEE_EXMPT_YN = "";
scwin.LD_MKT_TP_CD = "";
scwin.PAY_TP_CD = "A";
scwin.params = new Array();

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        $c.libRoundPanel.PanelToGroupBox(panel_Item);
        btn_print_old.hide(); // rexpert

        // (3393)유가도 환율정보 입력 가능 2011.03 - label_12
        if (js_market === "1" || js_market === "2") {
            panel_mkt_gubun_1.hide();
            panel_mkt_gubun_2.hide();
            label_12.show("");
            if (js_market === "1") {
                let strANULFEE_EXMPT_YN = "A^전체,Y^Y,N^N";
                cmb_ANULFEE_EXMPT_YN.CBData = strANULFEE_EXMPT_YN;
                cmb_ANULFEE_EXMPT_YN.setSelectedIndex(0);
                $c.cm.setColumnProp(grd_main, 'ANULFEE_EXMPT_AMT', 'show', false);
                $c.cm.setColumnProp(grd_main, 'ANULFEE_REAL_PAY_AMT', 'show', false);
            } else {
                let strANULFEE_EXMPT_YN = "A^전체,Y^Y,E^Y(일부면제),N^N";
                cmb_ANULFEE_EXMPT_YN.CBData = strANULFEE_EXMPT_YN;
                cmb_ANULFEE_EXMPT_YN.setSelectedIndex(0);
                $c.cm.setColumnProp(grd_main, 'ANULFEE_EXMPT_AMT', 'show', true);
                $c.cm.setColumnProp(grd_main, 'ANULFEE_REAL_PAY_AMT', 'show', true);
            }
        } else {
            panel_mkt_gubun_1.show("");
            panel_mkt_gubun_2.show("");
            label_12.show("");
            let strANULFEE_EXMPT_YN = "A^전체,Y^Y,E^Y(일부면제),N^N";
            cmb_ANULFEE_EXMPT_YN.CBData = strANULFEE_EXMPT_YN;
            cmb_ANULFEE_EXMPT_YN.setSelectedIndex(0);
            $c.cm.setColumnProp(grd_main, 'ANULFEE_EXMPT_AMT', 'show', false);
            $c.cm.setColumnProp(grd_main, 'ANULFEE_REAL_PAY_AMT', 'show', false);
        }
        await scwin.setCode();
        await scwin.listSync();
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);

        /*if(js_market == "2"  ){*/
        let basYear = 2014;
        if (parseInt(scwin.BAS_YY) >= basYear) {
            label_basYY1.hide();
            label_basYY2.show("");
            /*showObj(pan_KOSDAQ, true);*/
            // showObj(pan_PAY_TP_CD, true);
            pan_NewUnSchedule.show("");
        } else {
            label_basYY1.show("");
            label_basYY2.hide();
            /*showObj(pan_KOSDAQ, false);*/
            // showObj(pan_PAY_TP_CD, false);
            pan_NewUnSchedule.hide();
        }
        lbl_anualFeeInfo1.show("");
        lbl_anualFeeInfo2.show("");
        /*}*/
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40800.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
