 * @description Cal Cul On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_CalCul_OnFail = async function() {
    try {
        // alert(getMessageParam("MSG-0002", ""));
        await $c.win.alert($c.stf.getMessageParam("MSG-0002", "") + "\n" + trs_CalCul.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40800.trs_CalCul_OnFail" });
    }
};

/**
 * @method
 * @name trs_CalCul_OnSuccess
 * @description Cal Cul On Success 처리
 * @returns {Promise<void>}
