 */
scwin.trs_CalCul_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0001", ""));
        await scwin.setCode();
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40800.trs_CalCul_OnSuccess" });
    }
};

