/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    scwin.BAS_YY = cmb_BAS_YY.BindColVal;
    scwin.COM_NM = txb_COM_NM.getValue();
    scwin.ANULFEE_EXMPT_YN = cmb_ANULFEE_EXMPT_YN.BindColVal;
    scwin.PAY_TP_CD = cmb_PAY_TP_CD.BindColVal;
    scwin.setMarket();
    const sbmOptions = {
        id : "sbm_dts_ANULFEE_NOTI_BAS",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_ANULFEE_NOTI_BAS=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (scwin.ANULFEE_EXMPT_YN === "A") {
        scwin.ANULFEE_EXMPT_YN = "";
    }
    url += "&BAS_YY=" + scwin.BAS_YY;
    url += "&COM_NM=" + scwin.COM_NM.replace("&", "＆");
    url += "&ANULFEE_EXMPT_YN=" + scwin.ANULFEE_EXMPT_YN;
    url += "&LD_MKT_TP_CD=" + scwin.LD_MKT_TP_CD;
    url += "&PAY_TP_CD=" + scwin.PAY_TP_CD;
    const sbmOptions2 = {
        id : "sbm_dts_yearAssessmentFee",
        action : "/YearAssessmentFeeManagement.do",
        ref : "",
        target : "dts_yearAssessmentFee=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let basYear = 2014;
    if (parseInt(scwin.BAS_YY) >= basYear) {
        $c.cm.setColumnProp(grd_main, 'CAP', 'show', false);
        $c.cm.setColumnProp(grd_main, 'AVG_MKTCAP', 'show', true);
    } else {
        $c.cm.setColumnProp(grd_main, 'CAP', 'show', true);
        $c.cm.setColumnProp(grd_main, 'AVG_MKTCAP', 'show', false);
    }
    if (scwin.LD_MKT_TP_CD === "1") {
        //    유가
        $c.cm.setColumnProp(grd_main, 'ANULFEE_EXMPT_AMT', 'show', false);
        $c.cm.setColumnProp(grd_main, 'ANULFEE_REAL_PAY_AMT', 'show', false);
    } else {
        //    코스닥(면제금액,실납부금액)
        $c.cm.setColumnProp(grd_main, 'ANULFEE_EXMPT_AMT', 'show', true);
        $c.cm.setColumnProp(grd_main, 'ANULFEE_REAL_PAY_AMT', 'show', true);
    }
};

/**
 * @method
 * @name calcul
 * @description 연부과금 생성 fn_HoldyYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calcul = async function() {
    const gYYYY = $c.ut.cGetToday("yyyymmdd").substring(0, 4);
    let rtn = confirm(gYYYY + '년(부과년도기준) 연부과금을 생성 하시겠습니까?');
    if (rtn === 1) {
        scwin.setMarket();
        const sbmOptions = {
            id : "sbm_dts_CalCul",
            action : "/listingCommon.do",
            ref : "",
            target : "dts_CalCul=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        let gCnt = -1;
        dts_CalCul.insertRow();
        gCnt = dts_CalCul.getCellData(1, "CNT");
        if (gCnt > 0) {
            await $c.win.alert("이미 생성되었습니다.");
        } else {
            let url = "/YearAssessmentFeeManagement.do?SCREN_ID=" + "ULDSTF40800.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=createAnulfee";
            url += "&LD_MKT_TP_CD=" + scwin.LD_MKT_TP_CD;
            trs_CalCul.Action = encodeURI(url);
            // trs_CalCul.KeyName     = "toinb_dataid4";
            trs_CalCul.KeyValue = "JSP(I:pInput=dts_CalCul)";
            trs_CalCul.Post();
        }
    }
};

