scwin.setId = function(obj) {
    scwin.params[0] = dts_yearAssessmentFee.getCellData(Number(obj), "ISUR_CD");
    scwin.params[1] = dts_yearAssessmentFee.getCellData(Number(obj), "BAS_YY");
    scwin.params[2] = dts_yearAssessmentFee.getCellData(Number(obj), "LD_MKT_TP_CD");
    scwin.params[3] = dts_yearAssessmentFee.getCellData(Number(obj), "ANULFEE_NOTI_IMPOST_NO");
};

/**
